/**
 * Govern-discount types → ACC field mapping.
 * 'senior' → SC Discount
 * 'pwd'    → PWD Discount
 * 'naac' | 'medalOfValor' | 'soloParent' | 'diplomat' → Other Gov't Discount
 * 'mallPromo' | 'mallDiscount' | 'mallDisc' → Mall Discount
 * everything else ('regular', 'manager', 'storePromo', …) → Store Discount
 *
 * @param {import('./types').AccRow} row
 * @param {string} discType
 * @param {number} amount   PHP amount
 */
function applyDiscount(row, discType, amount) {
  if (!discType || amount <= 0) return;
  const t = (discType || '').toLowerCase();
  if (t === 'senior') {
    row.scDiscount += amount;
    row.noOfScDiscount++;
  } else if (t === 'pwd') {
    row.pwdDiscount += amount;
    row.noOfPwdDiscount++;
  } else if (['naac', 'soloparent', 'diplomat', 'medalofvalor'].includes(t)) {
    row.otherGovtDiscount += amount;
    row.noOfOtherGovtDiscount++;
  } else if (['mallpromo', 'malldiscount', 'malldisc'].includes(t)) {
    row.mallDiscount += amount;
    row.noOfMallDiscount++;
  } else {
    row.storeDiscount += amount;
    row.noOfStoreDiscount++;
  }
}

