class AccDataBuilder {
  /**
   * @param {Object} params
   * @param {number} params.sttUnx      Unix timestamp (seconds) – start of day
   * @param {number} params.endUnx      Unix timestamp (seconds) – end of day
   * @param {number[]} params.terminalNumbers   e.g. [1, 2]
   * @param {Record<number, number>} params.oldGrandTotals  termNo → PHP amount
   */
  constructor({ sttUnx, endUnx, terminalNumbers, oldGrandTotals }) {
    this._sttUnx = sttUnx;
    this._endUnx = endUnx;

    /** @type {Record<number, { hours: import('./types').AccRow[], allStrans: number, allEtrans: number }>} */
    this._terminals = {};

    for (const termNo of terminalNumbers) {
      const hours = Array.from({ length: 24 }, () => createEmptyRow());
      const oldGT = oldGrandTotals[termNo] ?? 0;
      for (const h of hours) {
        h.oldGrandTotal = oldGT;
        h.newGrandTotal = oldGT;
      }
      this._terminals[termNo] = {
        hours,
        allStrans: Infinity,
        allEtrans: -Infinity,
        oldGrandTotal: oldGT
      };
    }
  }

  /**
   * Process a single Transaction.
   * @param {import('./models/Transaction')} $txn
   */
  process($txn) {
    const txnKey = parseInt($txn.key, 10);
    if (txnKey < this._sttUnx || txnKey > this._endUnx) return this;

    const termNo =
      parseInt(
        $txn.original?.terminalNumber ?? $txn.original?.terminal ?? '1',
        10
      ) || 1;

    if (!this._terminals[termNo]) {
      const hours = Array.from({ length: 24 }, () => createEmptyRow());
      this._terminals[termNo] = {
        hours,
        allStrans: Infinity,
        allEtrans: -Infinity,
        oldGrandTotal: 0
      };
    }

    const termData = this._terminals[termNo];
    const hour = Moment.unix(txnKey).tz('Asia/Manila').hour();
    const row = termData.hours[hour];

    /** @type {import('./models/TransactionItem')[]} */
    const $items = Object.values($txn.items).filter(Boolean);
    const salesItems = $items.filter(
      $itm => !$itm.original?.refund && !$itm.original?.voided
    );
    const refundItems = $items.filter($itm => !!$itm.original?.refund);
    const voidItems = $items.filter($itm => $itm.original?.voided);

    // Voided items: sum amounts for ACC Fields 38-39 (voidAmount, noOfVoids).
    // Increment noOfVoids once per transaction (not per item), per ACC spec.
    // Voided items are excluded from salesItems so they don't affect any
    // financial fields or noOfTransactions (Field 20 excludes voids).
    if (voidItems.length > 0) {
      for (const $itm of voidItems) {
        row.voidAmount += Math.abs($itm.total ?? 0) / MP;
      }
      row.noOfVoids++;
    }

    for (const $itm of salesItems) {
      if ($itm._parts?.values) {
        for (const part of Object.values($itm._parts.values)) {
          const svc = Math.abs(part.service ?? 0) / MP;
          row.serviceCharge += svc;

          switch (part.vatType) {
            case 'vatable': {
              const vat = Math.abs(part.vat) / MP;
              row.vatAmount += vat;
              row.vatableSales +=
                (Math.abs(part.netSales) - Math.abs(part.vat)) / MP;
              break;
            }
            case 'vatExempt': {
              row.vatExemptSales += Math.abs(part.netSales) / MP;
              row.lessVatExemptAmount += Math.abs(part.vatExemption) / MP;
              break;
            }
            case 'zeroVat': {
              row.zeroRatedSales += Math.abs(part.netSales) / MP;
              row.lessVatExemptAmount += Math.abs(part.vatExemption) / MP;
              break;
            }
            default:
              break;
          }
        }
      } else {
        const itemService = Math.abs($itm.service ?? 0) / MP;
        row.serviceCharge += itemService;

        switch ($itm.vatType) {
          case 'vatable': {
            const vat = Math.abs($itm.vat) / MP;
            row.vatAmount += vat;
            row.vatableSales +=
              (Math.abs($itm.netSales) - Math.abs($itm.vat)) / MP;
            break;
          }
          case 'vatExempt': {
            row.vatExemptSales += Math.abs($itm.netSales) / MP;
            row.lessVatExemptAmount += Math.abs($itm.vatExemption) / MP;
            break;
          }
          case 'zeroVat': {
            row.zeroRatedSales += Math.abs($itm.netSales) / MP;
            row.lessVatExemptAmount += Math.abs($itm.vatExemption) / MP;
            break;
          }
          default:
            break;
        }
      }
    }

    // Determine which hourly bucket refund items should land in.
    // Refund items carry a numeric unix timestamp in original.refund (set when the
    // refund action was performed). If that timestamp falls within the current day's
    // range, bucket refunds into that hour. If it's outside the range the refund
    // belongs to a different day's file — skip it. Non-numeric values (e.g. boolean
    // true in legacy/test data) fall back to the transaction hour for backward compat.
    let refundRow = row;
    let refundInRange = refundItems.length > 0;
    if (refundItems.length > 0) {
      const firstRefundTs = refundItems[0].original?.refund;
      if (typeof firstRefundTs === 'number' && !isNaN(firstRefundTs)) {
        if (firstRefundTs >= this._sttUnx && firstRefundTs <= this._endUnx) {
          const refundHour = Moment.unix(firstRefundTs)
            .tz('Asia/Manila')
            .hour();
          refundRow = termData.hours[refundHour];
        } else {
          refundInRange = false;
        }
      }
    }

    if (refundInRange) {
      const saleDiscountTotal = salesItems.reduce(
        (s, si) =>
          s + Math.abs(si.txnDiscount || 0) + Math.abs(si.itmDiscount || 0),
        0
      );
      if (salesItems.length > 0 && saleDiscountTotal > 0) {
        // Per mall requirement, refunds are presented at the original gross amount
        // (before discount) when the sale had discounts applied.
        // Gross = sum of sale items' net paid + all discounts.
        let grossRefundAmt = 0;
        for (const si of salesItems) {
          grossRefundAmt +=
            (Math.abs(si.netSales || 0) +
              Math.abs(si.vatExemption || 0) +
              Math.abs(si.txnDiscount || 0) +
              Math.abs(si.itmDiscount || 0)) /
            MP;
        }
        refundRow.refunds += grossRefundAmt;
      } else {
        // No discounts or refund-only: use the refund item total directly.
        for (const $itm of refundItems) {
          refundRow.refunds += Math.abs($itm.total) / MP;
        }
      }
      refundRow.noOfRefunds++;
      refundRow.refundCounter++;
    }

    if (salesItems.length > 0) {
      row.noOfTransactions++;
    }
    if (salesItems.length > 0) {
      row.noOfCustomers++;
    }

    const discByType = /** @type {Record<string, number>} */ ({});

    // Collect transaction-level discount per-salesItem to avoid the aggregate
    // $txn.txnDiscount being cancelled to zero when a refund item (qty<0) with
    // the same discountSubtotal is included in the same transaction node.
    for (const $itm of salesItems) {
      const txnD = Math.abs($itm.txnDiscount) / MP;
      const txnT = $itm.txnDiscType;
      if (txnD > 0 && txnT) {
        discByType[txnT] = (discByType[txnT] ?? 0) + txnD;
      }
    }

    for (const $itm of salesItems) {
      const itmD = Math.abs($itm.itmDiscount) / MP;
      const itmT = $itm.itmDiscType;
      if (itmD > 0 && itmT) {
        discByType[itmT] = (discByType[itmT] ?? 0) + itmD;
      }
    }

    for (const $itm of salesItems) {
      if (!$itm.original?.paxDiscount || !$itm._parts?.values) continue;
      for (const [discType, part] of Object.entries($itm._parts.values)) {
        const paxD = Math.abs(part.discount ?? 0) / MP;
        if (paxD > 0) {
          discByType[discType] = (discByType[discType] ?? 0) + paxD;
        }
      }
    }

    for (const [discType, amount] of Object.entries(discByType)) {
      applyDiscount(row, discType, amount);
      row.totalDiscounts += amount;
      row.noOfTotalDiscounts++;
    }

    const receiptNo = $txn.original?.receiptNo;
    if (receiptNo != null && !isNaN(receiptNo)) {
      if (receiptNo < termData.allStrans) termData.allStrans = receiptNo;
      if (receiptNo > termData.allEtrans) termData.allEtrans = receiptNo;
    }

    // Only record payments for transactions with actual sales items.
    // Void-only transactions (all items voided) must not populate payment fields.
    if (salesItems.length > 0) {
      const payments = $txn.payments ?? [];
      if (payments.length > 0) {
        for (const pay of payments) {
          const payVal = (pay.value ?? 0) / MP;
          if (payVal > 0) applyPayment(row, pay.type, payVal);
        }
      } else {
        // Use salesItems total sum instead of $txn.total: Firebase zeroes out
        // $txn.total when an item is refunded, causing the payment to be dropped.
        const salesTotal =
          salesItems.reduce((sum, $itm) => sum + ($itm.total ?? 0), 0) / MP;
        if (salesTotal > 0) applyPayment(row, $txn.paymentType, salesTotal);
      }
    }

    return this;
  }

  /**
   * Build the final `AccDayData` structure, computing per-terminal daily
   * summaries and grand total row, ready for `calcDailyFile`.
   *
   * @param {{ previousZCount: number, currentZCount: number }} zCounts
   * @returns {import('./types').AccDayData}
   */
  build({ previousZCount = 0, currentZCount = 1 } = {}) {
    const terminals = Object.entries(this._terminals)
      .sort(([a], [b]) => parseInt(a, 10) - parseInt(b, 10))
      .map(([termNoStr, termData]) => {
        const termNo = parseInt(termNoStr, 10);
        const hours = termData.hours;

        // ACC Field 6: Gross = F7+F8+F9+F10+F11+F12+F13+F14+F22+F36
        for (const h of hours) {
          h.grossSales =
            Math.round(
              (h.vatableSales +
                h.vatAmount +
                h.vatExemptSales +
                h.lessVatExemptAmount +
                h.zeroRatedSales +
                h.localTax +
                h.serviceCharge +
                h.otherSurcharge +
                h.totalDiscounts +
                h.refunds) *
                100
            ) / 100;
        }

        // Daily summary = sum of all hourly rows
        const dailySummary = createEmptyRow();
        for (const h of hours) {
          addRows(dailySummary, h);
        }

        // ACC Field 15: Net = F6-F8-F10-F12-F13-F14-F24-F26-F28-F36
        dailySummary.netSales =
          Math.round(
            (dailySummary.grossSales -
              dailySummary.vatAmount -
              dailySummary.lessVatExemptAmount -
              dailySummary.localTax -
              dailySummary.serviceCharge -
              dailySummary.otherSurcharge -
              dailySummary.scDiscount -
              dailySummary.pwdDiscount -
              dailySummary.otherGovtDiscount -
              dailySummary.refunds) *
              100
          ) / 100;

        // Grand total
        dailySummary.oldGrandTotal = termData.oldGrandTotal;
        dailySummary.newGrandTotal =
          Math.round((termData.oldGrandTotal + dailySummary.grossSales) * 100) /
          100;

        // Receipt range (only meaningful in 99 row)
        const strans = termData.allStrans === Infinity ? 0 : termData.allStrans;
        const etrans =
          termData.allEtrans === -Infinity ? 0 : termData.allEtrans;
        dailySummary.strans = strans;
        dailySummary.etrans = etrans;

        // Z counts go on the 99 (daily summary) row only
        dailySummary.previousZCount = previousZCount;
        dailySummary.currentZCount = currentZCount;

        // ACC Field 15: Net = F6-F8-F10-F12-F13-F14-F24-F26-F28-F36
        for (const h of hours) {
          h.netSales =
            Math.round(
              (h.grossSales -
                h.vatAmount -
                h.lessVatExemptAmount -
                h.localTax -
                h.serviceCharge -
                h.otherSurcharge -
                h.scDiscount -
                h.pwdDiscount -
                h.otherGovtDiscount -
                h.refunds) *
                100
            ) / 100;
        }

        return {
          terminalNumber: termNo,
          hours,
          dailySummary
        };
      });

    return { terminals };
  }
}

module.exports = { AccDataBuilder };
